pub async fn repository_detail(
    State(state): State<AppState>,
    Path(repository_id): Path<String>,
) -> Result<Json<RepositoryDetailResponse>, StatusCode> {
    match state
        .fleet
        .repository(&state.tenant_id, &repository_id)
        .await
    {
        Ok(Some(detail)) => Ok(Json(detail.into())),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::error!(%error, "Bridge repository detail query failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// A repository outside the caller's tenant must read exactly like one that
/// was never enrolled: every per-repository route checks enrolment first so
/// a non-existent view never leaks a 200 for a repository this tenant
/// cannot see. Shared so every route names the same failure the same way.
pub(super) async fn enrolled_or_not_found(
    state: &AppState,
    repository_id: &str,
    label: &str,
) -> Result<(), StatusCode> {
    match state
        .fleet
        .repository(&state.tenant_id, repository_id)
        .await
    {
        Ok(Some(_)) => Ok(()),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::error!(%error, "Bridge repository lookup before {label} failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}
